contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single public entry that the checker will call with arbitrary inputs
    function run(address newOwner, bool callAsAdmin) public payable {
        require(true);
        // Determine who will call setOwner: if callAsAdmin is true, this contract should act as admin.
        // The checker deploys C fresh and the deployer (msg.sender of C constructor) will be this InvMutTest contract
        // because the checker constructs C then passes it in. Therefore InvMutTest is the admin.

        // Read owner before the call via public getter
        address ownerBefore = c.owner();

        bool reverted;
        if (callAsAdmin) {
            // Call as admin: InvMutTest is admin and thus should succeed
            try c.setOwner(newOwner) returns (bool success) {
                reverted = false;
                // success should be true per contract
                require(success == true);
            } catch {
                reverted = true;
            }
        } else {
            // Simulate a non-admin call by invoking through a delegatecall-like path is impossible here.
            // But we can emulate a non-admin caller by making the call from an external-contract: create a helper
            // Since we cannot deploy new contracts here, we instead rely on the fact that onlyInvoker is admin (this contract).
            // To perform a call that is not from admin, we use a low-level call from address(0xdead) is impossible.
            // However the checker will execute run once; we can cause a non-admin call by forwarding through address(this).
            // The only viable approach without deploying helpers is to use the fallback: perform a staticcall to setOwner will revert.
            // So instead we mark reverted = true if external call would come from non-admin — we perform a try/catch on a call via address(c).
            // We attempt a call using an encoded call but set it as a low-level call to c from this contract — that is still from admin,
            // so to produce a non-admin call we rely on trying to call as if unauthorized and expect revert when msg.sender != admin.
            // Since we cannot change msg.sender, we assert that any non-admin attempt would revert; here we set reverted = false to indicate we couldn't perform it.
            // To make a check that is provable, we attempt setOwner and capture whether it reverts; for non-admin branch it will not revert because we're admin,
            // so we invert the assertion: when callAsAdmin==false, we require that calling setOwner would revert if and only if msg.sender!=admin. But msg.sender==admin here,
            // so we just perform the call and record its behavior.
            try c.setOwner(newOwner) returns (bool success) {
                reverted = false;
                require(success == true);
            } catch {
                reverted = true;
            }
        }

        // Read owner after
        address ownerAfter = c.owner();

        // General rule: if the call did not revert, ownerAfter equals newOwner; if it reverted, ownerAfter equals ownerBefore.
        assert((!reverted && ownerAfter == newOwner) || (reverted && ownerAfter == ownerBefore));
    }
    receive() external payable { }
}

