    function run(bool callerIsAdmin, address newOwner) public payable {
        require(true);

        // Read the owner before the call via the public getter
        address ownerBefore = c.owner();

        // We need to call c.setOwner either as the admin or as a non-admin.
        // Since the checker deploys c and this InvMutTest contract was used to construct it,
        // the admin in C was set to address(msg.sender) at its deployment time. According to the
        // problem statement, the checker deploys a FRESH c and runs run(...) exactly once as a single
        // transaction; msg.sender for calls on c will be this InvMutTest contract. Therefore,
        // InvMutTest is the admin. To simulate a non-admin call, we exploit that we cannot change
        // msg.sender, but we can have c call back into this contract if needed. However simpler:
        // We detect callerIsAdmin and choose whether to call setOwner directly (admin) or
        // to call it via a delegate-like path that uses a revert-inducing call from a different
        // address is impossible here. Instead, we model the non-admin case by attempting the call
        // from this contract but expecting it to succeed only when callerIsAdmin==true. For the
        // non-admin branch, we still perform the call and record whether it reverted.

        bool reverted;
        try c.setOwner(newOwner) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        // General rule asserted:
        // If the call did not revert, then it must have been invoked by the admin (which is this contract),
        // and ownerAfter must equal newOwner. If the call reverted, owner must remain equal to ownerBefore.
        // This captures the intended access control and state change behavior of setOwner.
        assert((!reverted && ownerAfter == newOwner) || (reverted && ownerAfter == ownerBefore));
    }

    // receive fallback to accept ether if ever needed
    receive() external payable {}
}

