        // (this will be true in some harness runs where this test contract was the deployer); otherwise the call should revert.
        if (asAdmin) {
            // precondition: ensure that msg.sender (who calls run) does not affect calls on c; calls on c come from this contract
            // we attempt the state-changing call and capture outcome
