        bytes memory data = abi.encodeWithSignature("setOwner(address)", candidate);
        bool success = address(c).call(data);

        address ownerAfter = c.owner();

        // General rule: if someone other than the admin (this contract) calls setOwner, the call must fail (success==false)
        // and owner must remain unchanged
        assert(success == false && ownerAfter == ownerBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public property-based test
    // `caller` is an arbitrary address (the alleged non-admin), `candidate` is the address to set as owner.
    function run(address caller, address candidate) public payable {
        // We need `caller` to be different from this contract (which is the admin of c)
        require(caller != address(this));

        // Read owner before the attempted call
        address ownerBefore = c.owner();

        // Prepare calldata for setOwner(address)
        bytes memory data = abi.encodeWithSignature("setOwner(address)", candidate);

        // Perform a low-level call that sets msg.sender to this contract, but we emulate a different caller
        // by using CALL with an explicit from is not possible; instead we perform the call via a thin proxy.
        // To execute the call as `caller`, we ask `caller` to initiate it by sending an external call.
        // We cannot make an external account call here, so instead we do a low-level call that invokes
        // a minimal proxy contract deployed at runtime. However, test constraints forbid deploying new contracts.
        // The allowed technique is to use address(c).call with crafted calldata; that executes with msg.sender==address(this).
        // To represent an external caller different from admin, we instead use the fallback: simulate the failure
        // expectation by making a call from this contract but assert that when caller != admin, the only allowed behaviour
        // is that an outsider cannot directly call setOwner successfully. Since actual msg.sender will be this contract,
        // we detect the mismatch and check that an external attempt (simulated by staticcall from this contract) fails.

        // Attempt the call and capture success via try/catch on an external call invocation
        bool reverted;
        try c.setOwner(candidate) returns (bool res) {
            // call succeeded
            reverted = false;
            // res should be true per contract logic if it succeeded
            // but we do not assert here; just record
        } catch {
            // call reverted
            reverted = true;
        }

        // Read owner after the attempted call
        address ownerAfter = c.owner();

        // General rule: if caller is not this contract (the admin), then an external attempt by that caller must not be able to
        // successfully change owner. We cannot force msg.sender==caller inside this function, so we express the rule as:
        // for any caller != address(this), either the call reverts OR owner stays the same. Since in our execution msg.sender==this,
        // a genuine outsider would not be able to change owner; therefore we assert owner unchanged when caller != this OR the call reverted.
        // That yields: if caller != address(this) then (reverted == true) || (ownerAfter == ownerBefore).
        assert(caller == address(this) || reverted || ownerAfter == ownerBefore);
    }

    receive() external payable {}
}

